style.css:
/* Pure OLED Black — Brave Search */

:root {
    /* Change these colors to customize the darkness */
    --my-bg: #000000;
    --my-card: #000000;
    --my-border: #111111;
    --my-text: #e5e5e5;
    --my-link: #aabaff;
}

/* main page */
html,
body {
    background: var(--my-bg) !important;
    background-color: #000000 !important;
    color: var(--my-text) !important;
    color-scheme: dark !important;
}

/* page containers and search results */
body div,
body main,
body section,
body article,
body aside,
body header,
body nav,
body footer {
    background-color: #000000 !important;
    border-color: var(--my-border) !important;
}

/* text */
body p,
body h1,
body h2,
body h3,
body span,
body label {
    color: var(--my-text) !important;
}

/* links */
body a {
    color: var(--my-link) !important;
}

/* search box */
body input,
body textarea {
    background: #050505 !important;
    color: #ffffff !important;
    border-color: #171717 !important;
}

/* borders */
body div,
body section,
body article {
    border-color: #111111 !important;
}

/* scrollbar */
* {
    scrollbar-color: #222222 #000000 !important;
}
